#!/usr/bin/env bash
# 022 -- TESTE da futura V1.0.274 (reservas do Airbnb pelo e-mail) numa copia em /tmp, so leitura do sistema:
# clona a fila (main = 1.0.273), aplica o pacote, roda os testes. Nada e instalado, nada vai para a fila.
set -u
exec 2>&1
T=$(mktemp -d /tmp/v274.XXXX); chmod 755 $T
echo "" | base64 -d > $T/v274.patch
echo "b90c1ea99fb6242fa77f548512919860b81d646ca6b18ee3b87bd25a58f3d591  $T/v274.patch" | sha256sum -c --quiet || { echo "pacote corrompido"; exit 1; }
cd /tmp
R() { sudo -n /opt/esteira-nuvem/com-segredos env -i PATH=/usr/local/bin:/usr/bin:/bin HOME=$T LANG=C.UTF-8 "$@"; }
R git -c safe.directory='*' clone -q /opt/pms-banana-ai-fila.git $T/repo 2>&1 | tail -2 || true
[ -d $T/repo ] || { echo "clone falhou (permissao?)"; ls -ld $T; exit 1; }
cd $T/repo && echo "main: $(R git -c safe.directory='*' log --oneline -1 | cut -c1-80)"
R git -c safe.directory='*' apply --3way --whitespace=nowarn $T/v274.patch 2>&1 | tail -5
VENV=/opt/PMS-Banana-AI/SISTEMA/.venv
cd $T/repo/SISTEMA
echo "== testes novos e vizinhos"
R $VENV/bin/pytest -o addopts="-p no:cacheprovider" -q -x api/app/entrada/tests/test_v1274_airbnb_reservas_pelo_email.py 2>&1 | tail -40 | cut -c1-240
R $VENV/bin/pytest -o addopts="-p no:cacheprovider" -q api/app/entrada api/app/channel 2>&1 | grep -E '^(FAILED|ERROR)|[0-9]+ (passed|failed)' | tail -25 | cut -c1-200
echo "== suite inteira"
S=$(R timeout 600 $VENV/bin/pytest -o addopts="-p no:cacheprovider" -q --maxfail=60 -p no:randomly api 2>&1); echo "$S" | grep -E '^(FAILED|ERROR)|[0-9]+ (passed|failed|error)' | tail -60 | cut -c1-200
